-- PT117-S3-Q2. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT117-S3-Q2$batch03$ AND q.stimulus=$batch03$Leatherbacks, the largest of the sea turtles, when subjected to the conditions of captivity, are susceptible to a wide variety of fatal diseases with which they would never come in contact if they lived in the wild. It is surprising, therefore, that the likelihood that a leatherback will reach its theoretical maximum life expectancy is about the same whether that animal is living in captivity or in the wild.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to resolve the apparent discrepancy?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT117-S3-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch03$4e0d31b1-37db-42db-a39a-40e976a4732d$batch03$) <> 4 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch03$4e0d31b1-37db-42db-a39a-40e976a4732d$batch03$) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT117-S3-Q2'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Comparing leatherbacks with other reptiles does not separate captivity from the wild.$batch03$), ($batch03$B$batch03$, $batch03$Sea turtles living longer than other marine animals says nothing about captivity versus the wild.$batch03$), ($batch03$C$batch03$, $batch03$Most wild leatherbacks die from predators, which captive ones never face. That is something bad about the wild to offset the diseases of captivity, so the two odds come out about equal.$batch03$), ($batch03$D$batch03$, $batch03$If few people can make captivity healthy, captive turtles should do worse, not equally well.$batch03$), ($batch03$E$batch03$, $batch03$Whether size shows age does not affect the chance of reaching maximum life expectancy.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT117-S3-Q2$batch03$ AND e.id=$batch03$4e0d31b1-37db-42db-a39a-40e976a4732d$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
